   if (!selectedPreference) {
     setErrorState(true);
     statusMessage.textContent = "";
     radioButtons[0].focus();
     return;
   }

   setErrorState(false);
   statusMessage.textContent = `Preference saved: ${selectedPreference.value}.`;
 });

