 const form = document.querySelector("#notification-form");
 const fieldset = document.querySelector("#notification-fieldset");
 const radioButtons = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));
 const errorMessage = document.querySelector("#notification-error");
 const statusMessage = document.querySelector("#form-status");

 function getSelectedPreference() {
   return radioButtons.find((radioButton) => radioButton.checked);
 }

 function setErrorState(hasError) {
   fieldset.classList.toggle("has-error", hasError);
   errorMessage.hidden = !hasError;
   fieldset.setAttribute(
     "aria-describedby",
     hasError ? "notification-help notification-error" : "notification-help"
   );

   radioButtons.forEach((radioButton) => {
     radioButton.setAttribute("aria-invalid", String(hasError));
   });
 }

 radioButtons.forEach((radioButton) => {
   radioButton.addEventListener("change", () => {
     setErrorState(false);
     statusMessage.textContent = "";
   });
 });

 form.addEventListener("submit", (event) => {
   event.preventDefault();

   const selectedPreference = getSelectedPreference();

   if (!selectedPreference) {
     setErrorState(true);
     statusMessage.textContent = "";
     radioButtons[0].focus();
     return;
   }

   setErrorState(false);
   statusMessage.textContent = `Preference saved: ${selectedPreference.value}.`;
 });

