<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f5f7fb;
      --text: #111827;
      --muted: #5f6b7a;
      --border: #d8dee9;
      --primary: #2454d6;
      --primary-dark: #173ea8;
      --primary-soft: #eef3ff;
      --error: #b42318;
      --shadow: 0 24px 70px rgba(30, 41, 59, 0.16);
      --radius-lg: 28px;
      --radius-md: 18px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(36, 84, 214, 0.18), transparent 34rem),
        linear-gradient(135deg, #f8fbff 0%, var(--background) 45%, #edf2ff 100%);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 10;
      padding: 0.75rem 1rem;
      color: #ffffff;
      background: var(--primary);
      border-radius: 999px;
      transform: translateY(-150%);
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    .page-shell {
      display: grid;
      min-height: 100vh;
      place-items: center;
      padding: 2rem;
    }

    .card {
      width: min(100%, 42rem);
      padding: clamp(1.5rem, 4vw, 3rem);
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid rgba(216, 222, 233, 0.8);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      width: fit-content;
      margin-bottom: 1rem;
      padding: 0.35rem 0.75rem;
      color: var(--primary-dark);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      background: var(--primary-soft);
      border-radius: 999px;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 3.35rem);
      line-height: 1.04;
      letter-spacing: -0.05em;
    }

    .intro {
      max-width: 34rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .required-note {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .form-field {
      display: block;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin: 0;
      padding: 0;
      color: var(--text);
      font-size: 1.15rem;
      font-weight: 750;
    }

    .required-marker {
      color: var(--error);
    }

    .field-help,
    .field-error,
    .form-status {
      line-height: 1.5;
    }

    .field-help {
      margin: 0.45rem 0 1rem;
      color: var(--muted);
    }

    .radio-options {
      display: grid;
      gap: 0.8rem;
    }

    .radio-card {
      position: relative;
    }

    .radio-card input {
      position: absolute;
      inset-block-start: 1.25rem;
      inset-inline-start: 1.15rem;
      width: 1.15rem;
      height: 1.15rem;
      margin: 0;
      accent-color: var(--primary);
    }

    .radio-card label {
      display: grid;
      gap: 0.22rem;
      min-height: 4.35rem;
      padding: 1rem 1rem 1rem 3.2rem;
      background: #ffffff;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: border-color 160ms ease, background-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .radio-card label:hover {
      border-color: #9bb1ee;
      transform: translateY(-1px);
    }

    .radio-card input:checked + label {
      background: var(--primary-soft);
      border-color: var(--primary);
      box-shadow: 0 10px 28px rgba(36, 84, 214, 0.14);
    }

    .radio-card input:focus-visible + label {
      outline: 3px solid var(--primary);
      outline-offset: 4px;
    }

    .radio-title {
      font-weight: 750;
    }

    .radio-description {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .field-error {
      margin: 0.9rem 0 0;
      color: var(--error);
      font-weight: 650;
    }

    .has-error label {
      border-color: var(--error);
    }

    button {
      justify-self: start;
      min-height: 2.85rem;
      padding: 0.8rem 1.25rem;
      color: #ffffff;
      font: inherit;
      font-weight: 750;
      background: var(--primary);
      border: 0;
      border-radius: 999px;
      cursor: pointer;
      box-shadow: 0 14px 24px rgba(36, 84, 214, 0.22);
    }

    button:hover {
      background: var(--primary-dark);
    }

    button:focus-visible {
      outline: 3px solid #111827;
      outline-offset: 4px;
    }

    .form-status {
      min-height: 1.5rem;
      margin: 1.25rem 0 0;
      color: var(--primary-dark);
      font-weight: 700;
    }

    @media (max-width: 34rem) {
      .page-shell {
        padding: 1rem;
      }

      .card {
        border-radius: 22px;
      }

      button {
        width: 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      .card,
      .radio-card label,
      button,
      .eyebrow {
        border: 1px solid CanvasText;
      }

      .radio-card input:checked + label {
        outline: 2px solid SelectedItem;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content" class="page-shell">
    <section class="card" aria-labelledby="page-title">
      <div class="eyebrow">Preferences</div>
      <h1 id="page-title">Choose your notification style</h1>
      <p class="intro">Select the channel that works best for important product updates.</p>

      <form id="notification-form" novalidate>
        <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

        <div class="form-field">
          <fieldset id="notification-fieldset" aria-describedby="notification-help">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-marker" aria-hidden="true">*</span>
            </legend>
            <p id="notification-help" class="field-help">Choose one option.</p>

            <div class="radio-options">
              <div class="radio-card">
                <input id="notify-email" type="radio" name="notificationPreference" value="Email" required>
                <label for="notify-email">
                  <span class="radio-title">Email</span>
                  <span class="radio-description">Best for detailed updates and records.</span>
                </label>
              </div>

              <div class="radio-card">
                <input id="notify-sms" type="radio" name="notificationPreference" value="SMS" required>
                <label for="notify-sms">
                  <span class="radio-title">SMS</span>
                  <span class="radio-description">Fast alerts sent directly to your phone.</span>
                </label>
              </div>

              <div class="radio-card">
                <input id="notify-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                <label for="notify-push">
                  <span class="radio-title">Push Notifications</span>
                  <span class="radio-description">Timely prompts inside the app experience.</span>
                </label>
              </div>
            </div>

            <p id="notification-error" class="field-error" hidden>Error: Choose a notification preference.</p>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
      </form>

      <p id="form-status" class="form-status" role="status" aria-live="polite"></p>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const fieldset = document.querySelector("#notification-fieldset");
    const radioButtons = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));
    const errorMessage = document.querySelector("#notification-error");
    const statusMessage = document.querySelector("#form-status");

    function getSelectedPreference() {
      return radioButtons.find((radioButton) => radioButton.checked);
    }

    function setErrorState(hasError) {
      fieldset.classList.toggle("has-error", hasError);
      errorMessage.hidden = !hasError;
      fieldset.setAttribute(
        "aria-describedby",
        hasError ? "notification-help notification-error" : "notification-help"
      );

      radioButtons.forEach((radioButton) => {
        radioButton.setAttribute("aria-invalid", String(hasError));
      });
    }

    radioButtons.forEach((radioButton) => {
      radioButton.addEventListener("change", () => {
        setErrorState(false);
        statusMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedPreference = getSelectedPreference();

      if (!selectedPreference) {
        setErrorState(true);
        statusMessage.textContent = "";
        radioButtons[0].focus();
        return;
      }

      setErrorState(false);
      statusMessage.textContent = `Preference saved: ${selectedPreference.value}.`;
    });
  </script>
</body>
</html>
