 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: light;
       --background: #f5f7fb;
       --text: #111827;
       --muted: #5f6b7a;
       --border: #d8dee9;
       --primary: #2454d6;
       --primary-dark: #173ea8;
       --primary-soft: #eef3ff;
       --error: #b42318;
       --shadow: 0 24px 70px rgba(30, 41, 59, 0.16);
       --radius-lg: 28px;
       --radius-md: 18px;
     }

     * {
       box-sizing: border-box;
