       background:
         radial-gradient(circle at top left, rgba(36, 84, 214, 0.18), transparent 34rem),
         linear-gradient(135deg, #f8fbff 0%, var(--background) 45%, #edf2ff 100%);
     }

     .skip-link {
       position: absolute;
