       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       background: var(--primary-soft);
       border-radius: 999px;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 6vw, 3.35rem);
       line-height: 1.04;
       letter-spacing: -0.05em;
     }

     .intro {
       max-width: 34rem;
       margin: 1rem 0 2rem;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.6;
