       border: 0;
       border-radius: 999px;
       cursor: pointer;
       box-shadow: 0 14px 24px rgba(36, 84, 214, 0.22);
     }

     button:hover {
       background: var(--primary-dark);
     }

     button:focus-visible {
       outline: 3px solid #111827;
       outline-offset: 4px;
