 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content" class="page-shell">
     <section class="card" aria-labelledby="page-title">
       <div class="eyebrow">Preferences</div>
       <h1 id="page-title">Choose your notification style</h1>
       <p class="intro">Select the channel that works best for important product updates.</p>

       <form id="notification-form" novalidate>
         <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

         <div class="form-field">
           <fieldset id="notification-fieldset" aria-describedby="notification-help">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-marker" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="field-help">Choose one option.</p>

             <div class="radio-options">
               <div class="radio-card">
                 <input id="notify-email" type="radio" name="notificationPreference" value="Email" required>
                 <label for="notify-email">
                   <span class="radio-title">Email</span>
                   <span class="radio-description">Best for detailed updates and records.</span>
                 </label>
               </div>

               <div class="radio-card">
                 <input id="notify-sms" type="radio" name="notificationPreference" value="SMS" required>
                 <label for="notify-sms">
                   <span class="radio-title">SMS</span>
                   <span class="radio-description">Fast alerts sent directly to your phone.</span>
                 </label>
               </div>

               <div class="radio-card">
                 <input id="notify-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                 <label for="notify-push">
                   <span class="radio-title">Push Notifications</span>
                   <span class="radio-description">Timely prompts inside the app experience.</span>
                 </label>
               </div>
             </div>

             <p id="notification-error" class="field-error" hidden>Error: Choose a notification preference.</p>
           </fieldset>
         </div>

         <button type="submit">Save preference</button>
       </form>

       <p id="form-status" class="form-status" role="status" aria-live="polite"></p>
     </section>
   </main>

   <script>
     const form = document.querySelector("#notification-form");
     const fieldset = document.querySelector("#notification-fieldset");
     const radioButtons = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));
     const errorMessage = document.querySelector("#notification-error");
     const statusMessage = document.querySelector("#form-status");

     function getSelectedPreference() {
       return radioButtons.find((radioButton) => radioButton.checked);
     }

     function setErrorState(hasError) {
       fieldset.classList.toggle("has-error", hasError);
       errorMessage.hidden = !hasError;
       fieldset.setAttribute(
         "aria-describedby",
         hasError ? "notification-help notification-error" : "notification-help"
       );

       radioButtons.forEach((radioButton) => {
         radioButton.setAttribute("aria-invalid", String(hasError));
       });
     }

     radioButtons.forEach((radioButton) => {
       radioButton.addEventListener("change", () => {
         setErrorState(false);
         statusMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedPreference = getSelectedPreference();

       if (!selectedPreference) {
         setErrorState(true);
         statusMessage.textContent = "";
         radioButtons[0].focus();
         return;
       }

       setErrorState(false);
       statusMessage.textContent = `Preference saved: ${selectedPreference.value}.`;
     });
   </script>
 </body>
